  const result = await generateText({
    model,
    messages: [
      { role: 'system', content: SUMMARY_RULES },
      ...thread.map((m) => ({ role: m.from === 'customer' ? 'user' : 'assistant', content: m.text })),
      { role: 'user', content: 'Summarise this thread.' },
    ],
  });
