export async function continueChat(model, history, userText, { customerId }) {
  const messages = [...history, { role: 'user', content: userText }];
  const result = await generateText({
    model,
    system: ORDER_RULES,
    tools: { orderLookup },
    experimental_context: { customerId },
    maxSteps: 4,
    messages,
  });

  const responseMessages = [];
  for (const step of result.steps || []) {
    if (step.toolCalls) {
      responseMessages.push({
        role: 'assistant',
        content: step.toolCalls.map(c => ({
          type: 'tool-call',
          toolCallId: c.toolCallId,
          toolName: c.toolName,
          args: c.args,
        })),
      });
    }
    if (step.toolResults) {
      responseMessages.push({
        role: 'tool',
        content: step.toolResults,
      });
    }
    if (step.text) {
      responseMessages.push({
        role: 'assistant',
        content: step.text,
      });
    }
  }

  return [...messages, ...responseMessages];
}

