    model,
    system: ORDER_RULES,
    tools: { orderLookup },
    experimental_context: { customerId },
    maxSteps: 4,
    messages,
  });

  const responseMessages = [];
  for (const step of result.steps || []) {
    if (step.toolCalls) {
      responseMessages.push({
        role: 'assistant',
        content: step.toolCalls.map(c => ({
          type: 'tool-call',
