          args: c.args,
        })),
      });
    }
    if (step.toolResults) {
      responseMessages.push({
        role: 'tool',
        content: step.toolResults,
      });
    }
    if (step.text) {
      responseMessages.push({
        role: 'assistant',
        content: step.text,
      });
    }
  }

  return [...messages, ...responseMessages];
