export async function answerAboutOrders(model, question, { customerId }) {
  let messages = [{ role: 'user', content: question }];
  const toolsUsed = [];
  let stepCount = 0;

  while (stepCount < 4) {
    const result = await generateText({
      model,
      system: ORDER_RULES,
      tools: { orderLookup },
      experimental_context: { customerId },
      messages,
    });

    stepCount++;

    if (result.text) {
      return { text: result.text, toolsUsed };
    }

    // Handle tool calls: reconstruct messages with tool calls and results
    if (result.response?.messages) {
      messages = [...messages, ...result.response.messages];

      // Extract tool names from the response
      const step = result.steps?.[0];
      if (step?.toolCalls) {
        toolsUsed.push(...step.toolCalls.map((c) => c.toolName));
      }
    } else {
      break;
    }
  }

  // If we exit the loop without getting text, return empty text
  return { text: '', toolsUsed };
}

