1	// Support assistant helpers. Migrated to AI SDK 7 (ai@7.0.x).
2	import { generateText, generateObject, tool } from 'ai';
3	import { z } from 'zod';
4	import { findOrder } from '../data/orders.js';
5	
6	const SUMMARY_RULES = 'You summarise support threads for the next agent on shift. Two sentences, no greetings.';
7	const ORDER_RULES = "You are Acme's order assistant. Only discuss the current customer's orders. Be brief.";
8	
9	/** Looks up one of the current customer's orders. The customer id comes from the call's context. */
10	const orderLookup = tool({
11	  description: "Look up one of the current customer's orders by id.",
12	  inputSchema: z.object({ orderId: z.string() }),
13	  execute: async ({ orderId }, { experimental_context }) => {
14	    const { customerId } = experimental_context;
15	    const order = findOrder(orderId);
16	    if (!order || order.customerId !== customerId) return { orderId, error: 'not found' };
17	    return { orderId, status: order.status, eta: order.eta };
18	  },
19	});
20	
21	/**
22	 * Summarises a support thread for the next agent on shift.
23	 * @param {import('ai').LanguageModel} model
24	 * @param {{ from: 'customer' | 'agent', text: string }[]} thread oldest first
25	 * @returns {Promise<{ summary: string, inputTokens: number, cachedInputTokens: number }>}
26	 *   the summary, the input tokens the call used, and how many of those were read from the provider's prompt cache
27	 */
28	export async function summarizeThread(model, thread) {
29	  const result = await generateText({
30	    model,
31	    system: SUMMARY_RULES,
32	    messages: [
33	      ...thread.map((m) => ({ role: m.from === 'customer' ? 'user' : 'assistant', content: m.text })),
34	      { role: 'user', content: 'Summarise this thread.' },
35	    ],
36	  });
37	  return {
38	    summary: result.text,
39	    inputTokens: result.usage.inputTokens,
40	    cachedInputTokens: result.usage.cachedInputTokens ?? 0,
41	  };
42	}
43	
44	/**
45	 * Answers a customer's question about their orders. The model may look up orders (at most 4 model calls);
46	 * it can only see orders that belong to `customerId`.
47	 * @param {import('ai').LanguageModel} model
48	 * @param {string} question
49	 * @param {{ customerId: string }} customer
50	 * @returns {Promise<{ text: string, toolsUsed: string[] }>} the answer and the names of the tools called, in order
51	 */
52	export async function answerAboutOrders(model, question, { customerId }) {
53	  let messages = [{ role: 'user', content: question }];
54	  const toolsUsed = [];
55	  let stepCount = 0;
56	
57	  while (stepCount < 4) {
58	    const result = await generateText({
59	      model,
60	      system: ORDER_RULES,
61	      tools: { orderLookup },
62	      experimental_context: { customerId },
63	      messages,
64	    });
65	
66	    stepCount++;
67	
68	    if (result.text) {
69	      return { text: result.text, toolsUsed };
70	    }
71	
72	    // Handle tool calls: reconstruct messages with tool calls and results
73	    if (result.response?.messages) {
74	      messages = [...messages, ...result.response.messages];
75	
76	      // Extract tool names from the response
77	      const step = result.steps?.[0];
78	      if (step?.toolCalls) {
79	        toolsUsed.push(...step.toolCalls.map((c) => c.toolName));
80	      }
81	    } else {
82	      break;
83	    }
84	  }
85	
86	  // If we exit the loop without getting text, return empty text
87	  return { text: '', toolsUsed };
88	}
89	
90	const ticketSchema = z.object({
91	  category: z.enum(['billing', 'shipping', 'bug', 'other']),
92	  urgent: z.boolean(),
93	});
94	
95	/**
96	 * Classifies a support ticket.
97	 * @param {import('ai').LanguageModel} model
98	 * @param {string} text the ticket text
99	 * @returns {Promise<{ category: 'billing' | 'shipping' | 'bug' | 'other', urgent: boolean }>} validated against the schema
100	 */
101	export async function classifyTicket(model, text) {
102	  const { object } = await generateObject({
103	    model,
104	    schema: ticketSchema,
105	    prompt: `Classify this support ticket:\n\n${text}`,
106	  });
107	  return object;
108	}
109	
110	/**
111	 * Continues an order-support chat by one user turn.
112	 * @param {import('ai').LanguageModel} model
113	 * @param {import('ai').ModelMessage[]} history earlier user, assistant and tool messages (no system messages)
114	 * @param {string} userText the customer's new message
115	 * @param {{ customerId: string }} customer
